// Product.tsx
import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import Button from '../Button'
import Tag from '../Tag'
import {
  Card,
  Descricao,
  Titulo,
  Infos,
  Imagem,
  Conteudo,
  Nota
} from './styles'
import star from '../../assets/images.nova/star.svg'
import Modal from '../Modal'  // Importando o modal

type Props = {
  title: string
  description: string
  infos: string[]
  image: string
  nota: number
  id: number
  $isHome?: boolean
}

const Product = ({
  description,
  image,
  infos,
  title,
  nota,
  id,
  $isHome = true
}: Props) => {
  const navigate = useNavigate()
  const [isModalOpen, setModalOpen] = useState(false)  // Estado para controlar o modal

  const openModal = () => {
    setModalOpen(true)  // Abre o modal
  }

  const closeModal = () => {
    setModalOpen(false)  // Fecha o modal
  }

  const handleNavigate = () => {
    if ($isHome) {
      navigate(`/prato/${id}`)  // Navega para a página do prato
    } else {
      openModal()  // Abre o modal na página do produto
    }
  }

  // Bloquear/desbloquear rolagem
  useEffect(() => {
    if (isModalOpen) {
      document.body.style.overflow = 'hidden'  // Bloqueia a rolagem
    } else {
      document.body.style.overflow = 'auto'  // Restaura a rolagem
    }

    // Limpeza ao desmontar
    return () => {
      document.body.style.overflow = 'auto'  // Garante que a rolagem seja restaurada
    }
  }, [isModalOpen])  // Efeito só é acionado quando 'isModalOpen' muda

  return (
    <>
      <Card $isHome={$isHome} onClick={handleNavigate}>
        {/* Renderiza Infos e Tags apenas se $isHome for true */}
        {$isHome && (
          <Infos>
            {infos.map((info) => (
              <Tag key={info}>{info}</Tag>
            ))}
          </Infos>
        )}
        <Imagem src={image} alt={title} $isHome={$isHome} />
        <Descricao>
          <div>
            <Titulo>{title}</Titulo>
            {$isHome && (
              <Nota>
                {nota}
                <img src={star} alt="Rating" />
              </Nota>
            )}
          </div>
          <Conteudo>{description}</Conteudo>
          <Button
            type="button"
            title={$isHome ? 'Saiba mais' : 'Adicionar ao carrinho'}
            onClick={handleNavigate}
            fullWidth={!$isHome}
            isHome={$isHome}
          >
            {$isHome ? 'Saiba mais' : 'Adicionar ao carrinho'}
          </Button>
        </Descricao>
      </Card>

      {/* Exibe o modal apenas se for clicado em um produto */}
      <Modal
        isOpen={isModalOpen}  // O modal será visível quando o estado for true
        onClose={closeModal}  // Função para fechar o modal
        image={image}
        title={title}
        description={description}
      />
    </>
  )
}

export default Product
